#!/usr/bin/env node
// @ts-check
/**
 * Renders `results/HISTORY.md`, the human-readable record of every suite's index over time, from
 * `results/history.json`: one section per suite of the registry, for the runs that carry it.
 * Regenerated by every full `npm run evals` and by `npm run evals:report`; a test asserts the committed
 * file is fresh.
 *
 *   node evals/tools/report.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { insideDir } from '../lib/paths.mjs';
import { normalizeHistoryEntry } from '../lib/results.mjs';

export const HISTORY_FILE = 'results/HISTORY.md';

/**
 * @typedef {{ id: string, name: string, movable: boolean, cls?: string }} EvalMeta
 * @typedef {{ id: string, indexName: string, describe: string, metrics: EvalMeta[] }} SuiteMeta
 * @typedef {{ label: string, date: string, sha?: string, scores: Record<string, number>, index: number }} SuiteRun
 */

/** @param {number} d */
const signed = (d) => (d > 0 ? `+${d.toFixed(1)}` : d.toFixed(1));
/** @param {string} s */
const bold = (s) => `**${s}**`;
/** @param {number} d */
const strongIfMoved = (d) => (d === 0 ? signed(d) : bold(signed(d)));
/** @param {number} a @param {number} b */
const delta = (a, b) => Math.round((a - b) * 10) / 10;
/** @param {EvalMeta} e */
const classOf = (e) => e.cls ?? (e.movable ? 'movable' : 'structural');
const STILL_NOTE = {
	structural: ' — structural; moves only with a documented breaking change',
	roadmap: ' — roadmap; moves with new components or features',
};

/**
 * The three sections (index over time, per-eval scores, what moved) for one suite.
 * @param {SuiteRun[]} runs sorted by date, all carrying this suite
 * @param {EvalMeta[]} evals
 * @param {string} h heading marker for the sections, e.g. `###`
 * @returns {string[]}
 */
function suiteSections(runs, evals, h) {
	const first = runs[0];
	const last = runs[runs.length - 1];
	const lines = [
		`${h} Index over time`,
		'',
		`| Run | Date | Commit | ${evals.map((e) => e.id).join(' | ')} | Index | Δ previous | Δ baseline |`,
		`| --- | --- | --- | ${evals.map(() => '---:').join(' | ')} | ---: | ---: | ---: |`,
	];
	runs.forEach((run, i) => {
		const prev = i === 0 ? null : runs[i - 1];
		const scores = evals.map((e) => (run.scores[e.id] ?? 0).toFixed(1)).join(' | ');
		const vsPrev = prev ? signed(delta(run.index, prev.index)) : '—';
		const vsBase = prev ? signed(delta(run.index, first.index)) : '—';
		lines.push(
			`| ${run.label} | ${run.date.slice(0, 10)} | \`${run.sha ?? 'unknown'}\` | ${scores} | **${run.index.toFixed(1)}** | ${vsPrev} | ${vsBase} |`
		);
	});

	lines.push(
		'',
		`${h} Per-eval scores`,
		'',
		`| ID | Eval | Class | ${runs.map((r) => r.label).join(' | ')} | Δ total |`,
		`| --- | --- | :---: | ${runs.map(() => '---:').join(' | ')} | ---: |`
	);
	/** @type {{ id: string, name: string, cls: string, moved: number }[]} */
	const movement = [];
	for (const e of evals) {
		const moved = delta(last.scores[e.id] ?? 0, first.scores[e.id] ?? 0);
		movement.push({ id: e.id, name: e.name, cls: classOf(e), moved });
		const cells = runs.map((r) => (r.scores[e.id] ?? 0).toFixed(1)).join(' | ');
		lines.push(`| ${e.id} | ${e.name} | ${classOf(e)} | ${cells} | ${strongIfMoved(moved)} |`);
	}
	const indexCells = runs.map((r) => bold(r.index.toFixed(1))).join(' | ');
	lines.push(`| — | **Index** | | ${indexCells} | **${signed(delta(last.index, first.index))}** |`);

	const movers = movement.filter((m) => m.moved !== 0).sort((a, b) => b.moved - a.moved);
	const still = movement.filter((m) => m.moved === 0);
	lines.push(
		'',
		`${h} What moved`,
		'',
		`From \`${first.label}\` (${first.index.toFixed(1)}) to \`${last.label}\` (${last.index.toFixed(1)}): ${signed(delta(last.index, first.index))} points over ${runs.length} runs.`,
		''
	);
	if (movers.length) {
		lines.push('Biggest movers:', '');
		for (const m of movers) lines.push(`- ${m.id} ${m.name} ${signed(m.moved)}`);
		lines.push('');
	}
	if (still.length) {
		lines.push('Unchanged across all runs:', '');
		for (const m of still) {
			const note = STILL_NOTE[/** @type {keyof typeof STILL_NOTE} */ (m.cls)] ?? '';
			lines.push(`- ${m.id} ${m.name} (${(last.scores[m.id] ?? 0).toFixed(1)})${note}`);
		}
		lines.push('');
	}
	return lines;
}

/**
 * The per-tier view of the newest run that carries one: the same evals, scored over the components of
 * each tier only, so a helper class cannot move the pattern figure. Empty for runs recorded before tiers.
 * @param {import('../lib/results.mjs').HistoryEntry|undefined} newest
 * @param {string} suiteId
 * @param {string} h heading marker
 * @returns {string[]}
 */
function tierSection(newest, suiteId, h) {
	const tiers = newest?.suites[suiteId]?.tiers;
	if (!tiers) return [];
	const lines = [
		`${h} Index by tier (${newest.label})`,
		'',
		'Each eval scored over the components of one tier only; the suite index above is the mean over every measured component.',
		'',
		'| Tier | Index | Evals that apply |',
		'| --- | ---: | --- |',
	];
	for (const [tier, t] of Object.entries(tiers)) {
		lines.push(`| ${tier} | **${t.index.toFixed(1)}** | ${Object.keys(t.scores).join(', ')} |`);
	}
	lines.push('');
	return lines;
}

/**
 * @param {any[]} history entries in either shape
 * @param {SuiteMeta[]} suites the registry (or any list of suites with their metrics)
 * @returns {string} Markdown
 */
export function renderHistory(history, suites) {
	const entries = history.map((e) => normalizeHistoryEntry(e)).sort((a, b) => a.date.localeCompare(b.date));
	const lines = [
		'# Eval indices — history',
		'',
		'Generated by `npm run evals:report` from `results/history.json` — do not edit by hand.',
		'Each row is one full run (`npm run evals --label <name>`); each index is the unweighted mean of its evals.',
		'',
	];
	for (const suite of suites) {
		const runs = entries
			.filter((e) => e.suites[suite.id])
			.map((e) => ({
				label: e.label,
				date: e.date,
				sha: e.sha,
				scores: e.suites[suite.id].scores,
				index: e.suites[suite.id].index,
			}));
		if (runs.length === 0) continue;
		const ids = suite.metrics.map((m) => m.id);
		const later = runs[0].label !== entries[0].label;
		const since = later ? ` Measured from \`${runs[0].label}\` on; earlier runs have no value.` : '';
		const newest = entries.findLast((e) => e.suites[suite.id]);
		lines.push(
			`## ${suite.indexName}`,
			'',
			`The ${suite.metrics.length} evals ${ids[0]}–${ids[ids.length - 1]}: ${suite.describe}.${since}`,
			'',
			...suiteSections(runs, suite.metrics, '###'),
			...tierSection(newest, suite.id, '###')
		);
	}
	lines.push(
		'Per-run details (raw measurements, per-component scores, unmeasured pairs) live in `results/<label>.json`.',
		''
	);
	return lines.join('\n');
}

/**
 * Write `results/HISTORY.md`.
 * @param {string} evalsDir
 * @param {any[]} history
 * @param {SuiteMeta[]} suites
 */
export function writeHistoryReport(evalsDir, history, suites) {
	const file = insideDir(evalsDir, HISTORY_FILE);
	fs.writeFileSync(file, renderHistory(history, suites));
	return file;
}

async function main() {
	const evalsDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
	const { SUITES } = await import('../suites.mjs');
	const history = JSON.parse(fs.readFileSync(insideDir(evalsDir, 'results', 'history.json'), 'utf8'));
	const file = writeHistoryReport(evalsDir, history, SUITES);
	process.stdout.write(`wrote ${path.relative(process.cwd(), file)}\n`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await main();
